    #[test]
    fn jit_int_tensor_param_and_construct() {
        // #274: i64/i32 element tensors — param binding + indexed read, plus
        // construct/write/read and an embedding gather through an i64 id. At
        // parity with the interpreter (the last full-forward-pass blocker).
        let param = "fn first[B,S](x: Tensor[i64,[B,S]]) -> i64 { x[0,1] }\n\
                     fn main() -> i64 { first([[5, 6]]) }";
        assert_eq!(jit_run_i64(param).unwrap(), 6);
        assert_jit_eq_interp(param);

        let construct = "fn main() -> i64 { let !t = forge.zeros[i32, [3]]  t[2] = 9  t[2] as i64 }";
        assert_eq!(jit_run_i64(construct).unwrap(), 9);
        assert_jit_eq_interp(construct);

        // embedding lookup: id read from an i64 tensor, used to gather an f32 row.
        let gather = "fn main() -> i64 {\n  let ids = [10, 20, 30]\n  \
                      let !emb = forge.zeros[f32, [40]]\n  emb[20] = 5.0\n  \
                      let id = ids[1]\n  emb[id] as i64\n}";
        assert_eq!(jit_run_i64(gather).unwrap(), 5);
        assert_jit_eq_interp(gather);
    }

    #[test]
    fn jit_rejects_match() {
        // match is now implemented; wildcard arm with integer scrutinee must work.
        let result = jit_run_i64(r#"
            fn main() -> i64 {
                match 1 { _ => 0 }
            }
        "#).expect("match should succeed");
        assert_eq!(result, 0);
    }

    #[test]
