    #[test]
    fn jit_scalar_broadcast_add() {
        // s .+ t lifts a scalar across every tensor element.
        let src = r#"
            fn main() -> i64 {
                let t = [1.0, 2.0, 3.0]
                sum(10.0 .+ t) as i64
            }
        "#;
        // [11, 12, 13] = 36
        assert_eq!(jit_run_i64(src).unwrap(), 36);
    }

