    #[test]
    fn jit_scalar_math_exp_sqrt() {
        let src = r#"
            fn main() -> i64 {
                # exp(0) = 1, sqrt(16) = 4 -> 5
                (exp(0.0) + sqrt(16.0)) as i64
            }
        "#;
        assert_eq!(jit_run_i64(src).unwrap(), 5);
    }

    #[test]
    fn jit_scalar_pow_operator() {
        // #261: `**` on scalar floats was not lowered (jit error `StarStar`).
        // Programs return `as i64` (jit_run_i64 reads the integer return reg);
        // fractional results are scaled by 1000 so truncation still discriminates.
        assert_eq!(jit_run_i64("fn main() -> i64 { (2.0 ** 10.0) as i64 }").unwrap(), 1024);
        assert_jit_eq_interp("fn main() -> i64 { (2.0 ** 10.0) as i64 }");        // 1024
        assert_jit_eq_interp("fn main() -> i64 { (9.0 ** 0.5 * 1000.0) as i64 }"); // 3000
        assert_jit_eq_interp("fn main() -> i64 { (2.0 ** 0.0) as i64 }");          // 1
        assert_jit_eq_interp("fn main() -> i64 { (2.0 ** (0.0 - 1.0) * 1000.0) as i64 }"); // 500
    }

    #[test]
    fn jit_top_level_const() {
        // #268: top-level `let NAME = <literal>` constants now lower in the JIT
        // (the SPEC §4.5 enum-discriminant idiom), at parity with the interpreter.
        // Previously: "jit slice 1 does not support top-level `let` bindings".
        let src = r#"
let TOK_EQ = 1
let SCALE  = 2
fn main() -> i64 { TOK_EQ + SCALE * 10 }
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 21);
        assert_jit_eq_interp(src);
    }

    #[test]
    fn jit_dotted_ops_on_scalars() {
        // #275: a dotted op on two scalars is the scalar op (the checker types it
        // that way); previously the JIT errored and the interp made a rank-0
        // tensor. `(i as f32) ./ 64.0` is the standard RoPE pattern.
        assert_eq!(jit_run_i64("fn main()->i64{ ((5.0) ./ (2.0)) as i64 }").unwrap(), 2); // 2.5
        assert_jit_eq_interp("fn main()->i64{ (((5.0) .+ (2.0)) .* (3.0)) as i64 }");      // 21
        assert_jit_eq_interp("fn main()->i64{ ((2.0) .^ (10.0)) as i64 }");                // 1024
        assert_jit_eq_interp("fn main()->i64{\n  let i = 3\n  let e: f32 = (i as f32) ./ (64.0)\n  (e * 1000.0) as i64\n}"); // 46
    }

    #[test]
    fn jit_scalar_as_bf16_cast() {
        // #262: scalar `as bf16`/`as f16`/`as tf32` was not lowered (jit error
        // `Bf16 not yet supported`), though `@cast(bf16){…}` worked. It's a no-op
        // (#179): the value passes through, demoting at a bf16 tensor store.
        let src = r#"
fn main() -> i64 {
    let !t = forge.uninit[bf16, [2]]
    t[0] = cos(0.0) as bf16
    t[1] = (2.0 ** 3.0) as f16
    (t[0] + t[1]) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 9); // 1 + 8
        assert_jit_eq_interp(src);
    }

    #[test]
    fn jit_scalar_math_log_sin_cos() {
        // log(e) ≈ 1, sin(0) = 0, cos(0) = 1 -> floor(1 + 0 + 1) = 2.
        // floor guards against the f32 log(e) = 0.99999994 rounding down to 1 via `as i64`.
        let src = r#"
            fn main() -> i64 {
                (log(2.718281828) + sin(0.0) + cos(0.0) + 0.5) as i64
            }
        "#;
        assert_eq!(jit_run_i64(src).unwrap(), 2);
    }

    #[test]
    fn jit_scalar_math_abs_floor_ceil() {
        // abs(-7.25) = 7.25, floor(3.7) = 3, ceil(3.2) = 4 -> 14.25 -> 14
        let src = r#"
            fn main() -> i64 {
                (abs(-7.25) + floor(3.7) + ceil(3.2)) as i64
            }
        "#;
        assert_eq!(jit_run_i64(src).unwrap(), 14);
    }

    #[test]
    fn jit_scalar_math_floor_ceil_f64_precision() {
        // #287: floor/ceil/abs must compute in f64 like the interpreter.
        // 2.00000005 rounds to exactly 2.0 in f32; in f64 its ceil is 3.
        let src = r#"
            fn main() -> i64 {
                ceil(2.00000005) as i64
            }
        "#;
        assert_eq!(jit_run_i64(src).unwrap(), 3);
    }

    #[test]
    fn jit_mean_arg_lowered_once() {
        // #288: mean's argument must be lowered exactly once — an impure
        // argument (here: a fn that bumps a global-ish counter via a model)
        // must run its side effects once, like the interpreter.
        let src = r#"
            fn bump(c: Tensor[f32, [1]]) -> Tensor[f32, [4]] {
                c[0] = c[0] + 1.0
                [1.0, 2.0, 3.0, 4.0]
            }
            fn main() -> i64 {
                let counter = [0.0]
                let m = mean(bump(counter))
                (m * 10.0) as i64 + (counter[0] * 100.0) as i64
            }
        "#;
        // mean = 2.5 -> 25; counter must be 1.0 -> +100 = 125 (not 225).
        assert_eq!(jit_run_i64(src).unwrap(), 125);
    }

