    // ─── match expressions ───────────────────────────────────────────────────

    #[test]
    fn jit_match_int_basic() {
        // Correct branch taken for integer literal match.
        let result = jit_run_i64(r#"
            fn main() -> i64 {
                let x = 2
                match x {
                    1 => 10,
                    2 => 20,
                    3 => 30,
                    _ => 99
                }
            }
        "#).expect("run");
        assert_eq!(result, 20);
    }

    #[test]
    fn jit_match_wildcard() {
        // Wildcard arm taken when no literal matches.
        let result = jit_run_i64(r#"
            fn main() -> i64 {
                let x = 7
                match x {
                    1 => 100,
                    2 => 200,
                    _ => 999
                }
            }
        "#).expect("run");
        assert_eq!(result, 999);
    }

    #[test]
    fn jit_match_stmt() {
        // match as a statement: side-effecting body, result discarded.
        let result = jit_run_i64(r#"
            fn main() -> i64 {
                let !out = 0
                let x = 3
                match x {
                    1 => { out = 10 },
                    3 => { out = 30 },
                    _ => { out = 99 }
                }
                out
            }
        "#).expect("run");
        assert_eq!(result, 30);
    }

