    #[test]
    fn jit_narrow_int_scalar_casts_parity() {
        // The JIT had no ScalarKind for i8/i16/u8/u16/u32/u64/int8, so scalar
        // casts to them errored ("not yet supported by the JIT"). They now lower
        // as i64-backed values matching the interpreter's apply_cast — integer
        // sources wrap (two's complement), float sources saturate to range.
        for src in [
            "fn main()->i64{ (300 as i8) as i64 }",
            "fn main()->i64{ (128 as i8) as i64 }",
            "fn main()->i64{ ((0-5) as u8) as i64 }",
            "fn main()->i64{ (300.0 as i8) as i64 }",
            "fn main()->i64{ (42.0 as i8) as i64 }",
            "fn main()->i64{ ((0.0-500.0) as i8) as i64 }",
            "fn main()->i64{ ((0.0-1.0) as u8) as i64 }",
            "fn main()->i64{ (300.0 as u8) as i64 }",
            "fn main()->i64{ (40000 as i16) as i64 }",
            "fn main()->i64{ (40000.0 as i16) as i64 }",
            "fn main()->i64{ (70000 as u16) as i64 }",
            "fn main()->i64{ (5000000000 as u32) as i64 }",
            "fn main()->i64{ (5000000000.0 as u32) as i64 }",
            "fn main()->i64{ (123 as u64) as i64 }",
            "fn main()->i64{ (200 as int8) as i64 }",
            // float→unsigned overflow must saturate to the target's max, not
            // collapse to 0 / signed-saturate (parity-hunt #4/#5).
            "fn main()->i64{ (1.0e20 as u32) as i64 }",
            "fn main()->i64{ ((0.0-1.0e20) as u32) as i64 }",
            "fn main()->i64{ (1.0e30 as u64) as i64 }",
            "fn main()->i64{ ((0.0-5.0) as u64) as i64 }",
        ] { assert_jit_eq_interp(src); }
    }

    #[test]
    fn jit_continue_in_for_loop_parity() {
        // The JIT lowered `continue` as a jump to the loop header, skipping the
        // for-loop increment → infinite hang. It now targets the increment block.
        assert_jit_eq_interp(
            "fn main()->i64{ let !s=0  for i in 0..5 { if i==2 { continue }  s=s+1 }  s }");
        assert_jit_eq_interp(
            "fn main()->i64{ let !s=0  for i in 0..10 { if i==3 { continue }  if i==6 { break }  s=s+i }  s }");
        assert_jit_eq_interp(
            "fn main()->i64{ let !s=0  for i in 0..3 { for j in 0..3 { if j==1 { continue }  s=s+1 } }  s }");
    }

