    // ─── vault.load / vault.load_npz (issue #171) ────────────────────────────

    #[test]
    fn jit_vault_load_raw_f32() {
        use std::io::Write;
        // Write 4 f32 values [1.0, 2.0, 3.0, 4.0] as raw little-endian bytes
        let mut f = tempfile::NamedTempFile::new().unwrap();
        for v in [1.0f32, 2.0, 3.0, 4.0] {
            f.write_all(&v.to_le_bytes()).unwrap();
        }
        f.flush().unwrap();
        let path = f.path().to_str().unwrap().to_string();
        // sum([1,2,3,4]) == 10 → returned as i64
        let src = format!(r#"
fn main() -> i64 {{
    let w = vault.load[f32, [4]]("{}")
    sum(w) as i64
}}"#, path);
        assert_eq!(jit_run_i64(&src).unwrap(), 10);
    }

    #[test]
    fn jit_vault_load_npz_f32() {
        use std::io::Write;
        // Build a minimal .npy v1 file for a 1-D f32 array [5.0, 6.0, 7.0, 8.0]
        let data: Vec<f32> = vec![5.0, 6.0, 7.0, 8.0];
        let header_str = "{'descr': '<f4', 'fortran_order': False, 'shape': (4,), }";
        // Pad so that (10 + header_len) % 64 == 0, then append '\n'
        let mut header_padded = header_str.to_string();
        while (10 + header_padded.len() + 1) % 64 != 0 {
            header_padded.push(' ');
        }
        header_padded.push('\n');
        let header_len = header_padded.len() as u16;
        let mut npy: Vec<u8> = Vec::new();
        npy.extend_from_slice(b"\x93NUMPY"); // magic
        npy.push(1); npy.push(0);            // version 1.0
        npy.extend_from_slice(&header_len.to_le_bytes());
        npy.extend_from_slice(header_padded.as_bytes());
        for v in &data {
            npy.extend_from_slice(&v.to_le_bytes());
        }

        // Build NPZ (ZIP archive containing "test_key.npy")
        let npz_file = tempfile::NamedTempFile::new().unwrap();
        let path = npz_file.path().to_str().unwrap().to_string();
        {
            let file = std::fs::File::create(&path).unwrap();
            let mut zip_writer = zip::ZipWriter::new(file);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);
            zip_writer.start_file("test_key.npy", options).unwrap();
            zip_writer.write_all(&npy).unwrap();
            zip_writer.finish().unwrap();
        }

        // sum([5,6,7,8]) == 26 → returned as i64
        let src = format!(r#"
fn main() -> i64 {{
    let w = vault.load_npz[f32, [4]]("{}", key="test_key")
    sum(w) as i64
}}"#, path);
        assert_eq!(jit_run_i64(&src).unwrap(), 26);
    }

    // ─── #177: vault.load_npz with runtime string key ────────────────────────

    /// `as str` cast from i64 to forge string — content verified via `==`.
    #[test]
    fn jit_int_to_str_basic() {
        assert_jit_eq_interp("fn main() -> i64 { if (42 as str) == \"42\" { 1 } else { 0 } }");
        assert_jit_eq_interp("fn main() -> i64 { if (0 as str) == \"0\" { 1 } else { 0 } }");
        assert_jit_eq_interp("fn main() -> i64 { if (-7 as str) == \"-7\" { 1 } else { 0 } }");
    }

    /// `+` on strings — concatenation.
    #[test]
    fn jit_string_concat_plus() {
        assert_jit_eq_interp(r#"fn main() -> i64 { if "hello" + " world" == "hello world" { 1 } else { 0 } }"#);
    }

    /// Full #177 pattern: build a runtime NPZ key via `+` and `as str`.
    #[test]
    fn jit_runtime_npz_key_format() {
        assert_jit_eq_interp(
            r#"fn main() -> i64 {
                let n: i64 = 5
                let key = "layers[" + (n as str) + "].wq"
                if key == "layers[5].wq" { 1 } else { 0 }
            }"#,
        );
    }

    /// Build NPZ key in a loop, verify each is distinct.
    #[test]
    fn jit_runtime_key_loop() {
        assert_jit_eq_interp(
            r#"fn main() -> i64 {
                let !ok: i64 = 1
                for i in 0..3 {
                    let key = "layers[" + (i as str) + "].w"
                    let expected = if i == 0 { "layers[0].w" }
                                   else if i == 1 { "layers[1].w" }
                                   else { "layers[2].w" }
                    if !(key == expected) { ok = 0 }
                }
                ok
            }"#,
        );
    }

    // ─── #176: forge.kv JIT — KV-array parameter + indexed stream-append ─────

    /// `[kv0, kv1]` literal creates a KvArray; passing it to a function
    /// that takes `[KV[...]; 2]` and appending in a loop both work.
    #[test]
    fn jit_kv_array_literal_and_pass() {
        assert_jit_eq_interp(
            r#"fn append_all(caches: [KV[f32, [1, ~, 2]]; 2]) -> f32 {
                let frame = forge.zeros[f32, [1, 1, 2]]
                for i in 0..2 {
                    caches[i] <- frame
                }
                0.0
            }
            fn main() -> f32 {
                let !k0 = forge.kv[f32, [1, ~, 2]](capacity = 4)
                let !k1 = forge.kv[f32, [1, ~, 2]](capacity = 4)
                let caches = [k0, k1]
                append_all(caches)
            }"#,
        );
    }

    /// After indexed appends the data is readable; sum over the materialized
    /// view reflects the appended frames (all-zeros → sum = 0).
    #[test]
    fn jit_kv_array_indexed_append_advances_len() {
        assert_jit_eq_interp(
            r#"fn fill(caches: [KV[f32, [1, ~, 4]]; 2], n: i64) -> i64 {
                let frame = forge.ones[f32, [1, 1, 4]]
                for _ in 0..n {
                    caches[0] <- frame
                    caches[1] <- frame
                }
                0
            }
            fn main() -> i64 {
                let !k0 = forge.kv[f32, [1, ~, 4]](capacity = 8)
                let !k1 = forge.kv[f32, [1, ~, 4]](capacity = 8)
                let caches = [k0, k1]
                fill(caches, 3)
            }"#,
        );
    }

    // ─── #178: forge.uninit JIT lowering ─────────────────────────────────────

    /// `forge.uninit[f32, [N]]` — allocate without zeroing; write-before-read
    /// keeps results deterministic across JIT and interpreter.
    #[test]
    fn jit_forge_uninit_1d_write_then_sum() {
        let src = r#"
fn main() -> i64 {
    let !t = forge.uninit[f32, [4]]
    t[0] = 1.0
    t[1] = 2.0
    t[2] = 3.0
    t[3] = 4.0
    sum(t) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 10);
    }

    /// `forge.uninit` with 2D shape — write every element then sum to verify layout.
    #[test]
    fn jit_forge_uninit_2d_fill_and_sum() {
        let src = r#"
fn main() -> i64 {
    let !g = forge.uninit[f32, [3, 3]]
    g[0, 0] = 1.0  g[0, 1] = 1.0  g[0, 2] = 1.0
    g[1, 0] = 1.0  g[1, 1] = 1.0  g[1, 2] = 1.0
    g[2, 0] = 1.0  g[2, 1] = 1.0  g[2, 2] = 1.0
    sum(g) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 9);
    }

    // ── #249: tensor value-copy semantics (no aliasing across binds) ─────────

    #[test]
    fn jit_let_bind_tensor_copies() {
        // `let !y = x` is a value copy: mutating y must not touch x. Pre-fix the
        // JIT aliased (both read 9); the interpreter copies (x=1, y=9).
        let src = r#"
fn main() -> i64 {
    let !x = forge.zeros[f32, [3]]
    x[0] = 1.0
    let !y = x
    y[0] = 9.0
    (x[0] + y[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 901); // x=1, y=9
    }

    #[test]
    fn jit_model_field_tensor_copies() {
        // A tensor stored into a model field is snapshotted: a later write
        // through the source tensor must not change the field.
        let src = r#"
model M { w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !t = forge.zeros[f32, [2]]
    let m = M { w: t }
    t[0] = 9.0
    m.w[0] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 0);
    }

    #[test]
    fn jit_aliased_args_isolated() {
        // `f(t, t)` with only the first param `!`: the mutation through `!a`
        // must not leak into the read of `b` during the call (both alias t in
        // the buggy JIT). interp: during=0, then t writes back to 50.
        let src = r#"
fn f[N](!a: Tensor[f32, [N]], b: Tensor[f32, [N]]) -> f32 {
    a[0] = 50.0
    b[0]
}
fn main() -> i64 {
    let !t = forge.zeros[f32, [3]]
    let during = f(t, t)
    (during + t[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 5000); // during=0, t[0]=50
    }

    #[test]
    fn jit_row_view_let_copies() {
        // `let !row = grid[0]` snapshots the row; writing row must not touch grid.
        let src = r#"
fn main() -> i64 {
    let !grid = forge.zeros[f32, [2, 3]]
    grid[0, 0] = 1.0
    let !row = grid[0]
    row[0] = 9.0
    grid[0, 0] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 1);
    }

    #[test]
    fn jit_single_arg_mut_writeback_preserved() {
        // Copy-in/copy-out must preserve the common case: a single `!` tensor
        // param mutated by the callee IS visible in the caller after return.
        let src = r#"
fn poke[N](!t: Tensor[f32, [N]]) -> nil { t[0] = 77.0  nil }
fn main() -> i64 {
    let !x = forge.zeros[f32, [3]]
    poke(x)
    x[0] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 77);
    }

    // ── #524: `let !y = m.<tensor field>` binds a LIVE ALIAS (SPEC §3.4) ─────
    //
    // The one carve-out from #249's value-copy rule above: a TENSOR model field
    // bound through the `!` spelling aliases the field, so every write through
    // the binding reaches it. `let mut y = m.w`, `let y = m.w`, a scalar field,
    // and a plain local all keep copying — the tests below pin both sides.

    #[test]
    fn jit_model_tensor_field_bind_aliases_element_write_524() {
        // Element write through the binding reaches the field. Pre-fix the JIT
        // copied here (m.w[0] stayed 0) while `dmc run` printed 42.
        let src = r#"
model M { !w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [2]] }
    let !y = m.w
    y[0] = 42.0
    m.w[0] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 42);
    }

    #[test]
    fn jit_model_tensor_field_bind_whole_assign_writes_through_524() {
        // Whole-binding `=` through the alias writes the FIELD; it must not
        // rebind the local and leave the field at its old contents.
        let src = r#"
model M { !w: Tensor[f32, [4]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [4]] }
    let !y = m.w
    y = forge.ones[f32, [4]] .* 7.0
    (m.w[0] + m.w[3]) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 14);
    }

    #[test]
    fn jit_model_tensor_field_bind_compound_assign_writes_through_524() {
        // `+=` on a tensor alias is the elementwise op, read from and written
        // back to the field — two bumps land as 2.
        let src = r#"
model M { !w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [2]] }
    let !y = m.w
    y += forge.ones[f32, [2]]
    y += forge.ones[f32, [2]]
    m.w[1] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 2);
    }

    #[test]
    fn jit_model_scalar_field_bind_copies_524() {
        // A SCALAR field binds its current VALUE — the snapshot must not track
        // a later write through the binding, and the field must not move.
        let src = r#"
model M { !n: i64 }
fn main() -> i64 {
    let !m = M { n: 7 }
    let !s = m.n
    s = 99
    m.n * 100 + s
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 799);
    }

    #[test]
    fn jit_let_mut_from_tensor_field_copies_524() {
        // `let mut y = m.w` is NOT the `!` spelling and never aliases — this is
        // exactly where the two mutable-binding forms differ (SPEC §3.4).
        let src = r#"
model M { !w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [2]] }
    let mut y = m.w
    y[0] = 42.0
    (m.w[0] + y[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 4200); // field 0, copy 42
    }

    #[test]
    fn jit_immutable_bind_from_tensor_field_copies_524() {
        // An immutable binding is a snapshot: a later element write to the
        // FIELD must not be visible through it.
        let src = r#"
model M { !w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [2]] }
    let y = m.w
    m.w[0] = 42.0
    (y[0] + m.w[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 4200); // snapshot 0, field 42
    }

    #[test]
    fn jit_field_alias_shadowed_by_plain_let_stops_writing_through_524() {
        // A later `let !y = <fresh tensor>` drops the alias: `y = …` after the
        // shadow must rebind the local, not write the field.
        let src = r#"
model M { !w: Tensor[f32, [2]] }
fn main() -> i64 {
    let !m = M { w: forge.zeros[f32, [2]] }
    let !y = m.w
    y[0] = 5.0
    let !y = forge.zeros[f32, [2]]
    y[0] = 9.0
    (m.w[0] + y[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 905); // field 5, shadow 9
    }

    // ── #553: a rebound `!` parameter writes back the buffer it now names ────
    //
    // A `!` tensor parameter is copy-in/copy-out (#249 above): the caller hands
    // the callee a private copy and copies that buffer back on return. A
    // whole-binding assignment in the callee rebinds the local to a FRESH forge
    // buffer, so the buffer the caller wrote back was the stale one it passed
    // in. Element writes never showed it — they mutate the copy in place — so
    // the gap only opened on reassignment.

    #[test]
    fn jit_mut_param_reassign_writes_back_553() {
        // The reported repro. Pre-fix: `dmc run` 220, `dmc jit` 120 — the loss
        // agreed, only the writeback diverged.
        let src = r#"
@grad fn f(!w: Tensor[f32, [2]]) -> f32 { w = w .* 2.0   sum(w .* w) }
fn main() -> i64 {
    let !w = forge.zeros[f32, [2]]
    w[0] = 1.0   w[1] = 2.0
    let s = f(w)
    (s + w[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 220); // loss 20, w[0] 2
    }

    #[test]
    fn jit_mut_param_reassign_writes_back_in_template_553() {
        // The other place a `!` parameter reaches the JIT: a template, where
        // `declare_template_signature` accepts one outside `@grad fn`. Same
        // defect, and `declare_monomorph` was dropping the indices that make
        // the copy-out fire.
        let src = r#"
fn scale[N](!t: Tensor[f32, [N]]) -> f32 {
    t = t .* 2.0
    t[0]
}
fn main() -> i64 {
    let !x = forge.zeros[f32, [3]]
    x[0] = 1.0
    let d = scale(x)
    (d + x[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 202); // callee saw 2, caller 2
    }

    #[test]
    fn jit_mut_param_reassign_leaves_other_params_alone_553() {
        // Only the reassigned parameter moves: `b` is `!` too but is never
        // rebound, so it comes back exactly as it went in.
        let src = r#"
@grad fn f(!a: Tensor[f32, [2]], !b: Tensor[f32, [2]]) -> f32 {
    a = a .* 3.0
    sum(a .* b)
}
fn main() -> i64 {
    let !a = forge.zeros[f32, [2]]
    let !b = forge.zeros[f32, [2]]
    a[0] = 1.0   a[1] = 2.0
    b[0] = 5.0   b[1] = 7.0
    let s = f(a, b)
    (s + a[0] * 100.0 + b[0] * 10000.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 50357); // loss 57, a[0] 3, b[0] 5
    }

    #[test]
    fn jit_mut_param_reassign_does_not_leak_through_an_aliased_arg_553() {
        // #249's isolation still holds: `f(t, t)` with only param 0 `!` must
        // not let the reassignment reach the plain `b` during the call.
        let src = r#"
@grad fn f(!a: Tensor[f32, [2]], b: Tensor[f32, [2]]) -> f32 {
    a = a .* 2.0
    sum(a) + sum(b)
}
fn main() -> i64 {
    let !t = forge.zeros[f32, [2]]
    t[0] = 1.0   t[1] = 2.0
    let s = f(t, t)
    (s + t[0] * 100.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 209); // during 9 (6+3), t[0] 2
    }

    #[test]
    fn jit_mut_param_no_reassign_still_writes_back_553() {
        // The copy-out is skipped when the parameter still names the buffer it
        // came in on — element writes had already landed there, and #249's
        // writeback carries them out unchanged.
        let src = r#"
fn poke[N](!t: Tensor[f32, [N]]) -> nil { t[0] = 77.0  nil }
fn main() -> i64 {
    let !x = forge.zeros[f32, [3]]
    poke(x)
    x[0] as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 77);
    }

    #[test]
    fn jit_mut_param_reassign_gradient_is_wrt_the_incoming_value_553() {
        // The copy-out runs after the backward pass, so it cannot disturb the
        // tape: `L = sum((2w).^2) = 4·sum(w²)`, so `∂L/∂w = 8w`.
        let src = r#"
@grad fn f(!w: Tensor[f32, [2]]) -> f32 { w = w .* 2.0   sum(w .* w) }
fn main() -> i64 {
    let !w = forge.zeros[f32, [2]]
    w[0] = 1.0   w[1] = 2.0
    let (l, g) = f.fwd_bwd(w)
    (l + g[0] * 100.0 + g[1] * 10000.0) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 160820); // loss 20, g = (8, 16)
    }

    #[test]
    fn jit_mut_param_fwd_bwd_does_not_write_back_553() {
        // `f.fwd_bwd(w)` passes the caller's own tensor with no copy-in and no
        // writeback on either backend. The copy-out must stay off that entry,
        // or the reassignment would clobber the caller's `w`.
        let src = r#"
@grad fn f(!w: Tensor[f32, [2]]) -> f32 { w = w .* 2.0   sum(w .* w) }
fn main() -> i64 {
    let !w = forge.zeros[f32, [2]]
    w[0] = 1.0   w[1] = 2.0
    let (l, _g) = f.fwd_bwd(w)
    (l + w[0] * 100.0 + w[1] * 10000.0) as i64
}
"#;
        assert_jit_eq_interp(src);
        assert_eq!(jit_run_i64(src).unwrap(), 20120); // loss 20, w unmoved (1, 2)
    }

    /// `forge.uninit` followed by element-wise copy from a known tensor.
    #[test]
    fn jit_forge_uninit_copy_from_source() {
        let src = r#"
fn main() -> i64 {
    let src = [10.0, 20.0, 30.0]
    let !dst = forge.uninit[f32, [3]]
    dst[0] = src[0]
    dst[1] = src[1]
    dst[2] = src[2]
    sum(dst) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 60);
    }

    // ─── #179: bf16/exotic tensor field types ────────────────────────────────

    /// Model with a bf16 tensor field: indexing works after #179 fix.
    #[test]
    fn jit_model_bf16_field_indexable() {
        let src = r#"
model W { data: Tensor[bf16, [4]] }
fn main() -> i64 {
    let t = forge.ones[f32, [4]]
    let m = W { data: t }
    sum(m.data) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 4);
    }

    /// #324: a bf16 weight FIELD drives the bf16-direct matmul end-to-end —
    /// f32 activation @ bf16 weight. Exercises the field store (f32→bf16
    /// down-convert), Bf16Tensor field access, and the bf16 matmul kernel.
    /// [1,2]·[2,3] of ones → [1,3] of 2.0 → sum 6.
    #[test]
    fn jit_bf16_field_matmul() {
        let src = r#"
model W { w: Tensor[bf16, [2, 3]] }
fn main() -> i64 {
    let x = forge.ones[f32, [1, 2]]
    let wt = forge.ones[f32, [2, 3]]
    let m = W { w: wt }
    sum(x @ m.w) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 6);
    }

    /// Model with f16 2D tensor field — indexing yields the right element.
    #[test]
    fn jit_model_f16_field_2d_index() {
        let src = r#"
model W { data: Tensor[f16, [2, 3]] }
fn main() -> i64 {
    let t = forge.zeros[f32, [2, 3]]
    t[1, 2] = 7.0
    let m = W { data: t }
    m.data[1, 2] as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 7);
    }

    /// Model with mixed exotic/native fields — tag field still works.
    #[test]
    fn jit_model_exotic_mixed_fields() {
        let src = r#"
model Layer {
    tag: i64,
    weights: Tensor[bf16, [4, 4]],
    bias: Tensor[f32, [4]],
}
fn main() -> i64 {
    let b = forge.zeros[f32, [4]]
    let w = forge.zeros[f32, [4, 4]]
    let lay = Layer { tag: 99, weights: w, bias: b }
    lay.tag
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 99);
    }

    // ─── #180: [Model; N] parameter + literal ────────────────────────────────

    /// Pass a `[Layer; 3]` literal to a function that indexes it.
    #[test]
    fn jit_model_array_index_field() {
        let src = r#"
model Layer { w: Tensor[f32, [2]] }
fn sum_layers(layers: [Layer; 3]) -> f32 {
    layers[0].w[0]
}
fn main() -> i64 {
    let l0 = Layer { w: forge.ones[f32, [2]] }
    let l1 = Layer { w: forge.ones[f32, [2]] }
    let l2 = Layer { w: forge.ones[f32, [2]] }
    sum_layers([l0, l1, l2]) as i64
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 1);
    }

