    // ─── #174: exact GeLU second derivative for second-order autodiff ─────────

    /// Verify gelu''(x) via finite differences on gelu'(x).
    /// gelu(x) = 0.5*x*(1 + tanh(c*(x + k*x³))).
    /// We differentiate `sum(gelu(W))` twice wrt W using @grad @grad and
    /// cross-check against a finite-difference estimate of the first gradient.
    #[test]
    fn jit_grad_grad_gelu() {
        let src = r#"
            @grad @grad fn f(!W: Tensor[f32, [3]]) -> f32 {
                sum(gelu(W))
            }
        "#;
        // At W = [0.5, 1.0, -0.5] compute gelu''(x) = d(gelu')/dx via FD.
        let w0 = [0.5_f32, 1.0, -0.5];
        let (_, grads2) = jit_grad_grad(src, "f", &[&w0], &[3]).unwrap();
        assert_eq!(grads2.len(), 1);
        let g2 = &grads2[0];

        // Finite-difference estimate of gelu'': (gelu'(x+eps) - gelu'(x-eps)) / (2*eps).
        // We compute gelu' using a first-order grad call.
        let src1 = r#"
            @grad fn f(!W: Tensor[f32, [3]]) -> f32 {
                sum(gelu(W))
            }
        "#;
        let eps = 1e-3_f32;
        for k in 0..3 {
            let mut wp = w0;
            let mut wm = w0;
            wp[k] += eps;
            wm[k] -= eps;
            let (_, gp) = jit_grad(src1, "f", &[&wp], &[3]).unwrap();
            let (_, gm) = jit_grad(src1, "f", &[&wm], &[3]).unwrap();
            let fd = (gp[0][k] - gm[0][k]) / (2.0 * eps);
            assert!(
                (fd - g2[k]).abs() < 0.05,
                "gelu'' FD[{}]={:.4} analytic={:.4}", k, fd, g2[k],
            );
        }
    }

    /// gelu'' must be non-zero for x near the origin (the zero approximation
    /// from the old TODO was only correct for large |x|).
    #[test]
    fn jit_grad_grad_gelu_nonzero_near_origin() {
        let src = r#"
            @grad @grad fn f(!W: Tensor[f32, [1]]) -> f32 {
                sum(gelu(W))
            }
        "#;
        let w = [0.5_f32]; // gelu''(0.5) ≈ 0.44, definitely not zero
        let (_, grads2) = jit_grad_grad(src, "f", &[&w], &[1]).unwrap();
        assert!(
            grads2[0][0].abs() > 0.1,
            "gelu'' at x=0.5 should be non-zero (≈0.44), got {}",
            grads2[0][0],
        );
    }

