    /// lispy.py pattern: named fns stored in a map, retrieved with type
    /// annotation, and called through the retrieved pointer.
    #[test]
    fn jit_closure_fn_in_map_lispy_pattern() {
        assert_jit_eq_interp(r#"
            fn add(x: i64, y: i64) -> i64 { x + y }
            fn sub(x: i64, y: i64) -> i64 { x - y }
            fn main() -> i64 {
                let !env = map_new()
                map_set(env, "+", add)
                map_set(env, "-", sub)
                let f: fn(i64, i64) -> i64 = map_get(env, "+")
                let g: fn(i64, i64) -> i64 = map_get(env, "-")
                f(10, 3) + g(10, 3)
            }
        "#);
    }

